Logger logger = new Logger();
logger.write("INFO", "First");
logger.write("INFO", "Second");
logger.write("INFO", "Third");
LogFilter filter = new LogFilter();
List<LogEntry> logs = logger.read(filter);
assert logs.get(0).message.equals("Third");
assert logs.get(2).message.equals("First");

Logger logger = new Logger();
logger.write("INFO", "Info msg");
logger.write("ERROR", "Error msg");
logger.write("INFO", "Info msg 2");
LogFilter filter = new LogFilter();
filter.level = "ERROR";
assert logger.read(filter).size() == 1;
filter.level = "INFO";
assert logger.read(filter).size() == 2;

Logger logger = new Logger();
logger.write("INFO", "Before");          // t=1000
logger.write("INFO", "In range 1");      // t=1500
logger.write("INFO", "In range 2");      // t=2000
logger.write("INFO", "After");           // t=3000
// Manually set timestamps for deterministic test
List<LogEntry> all = logger.read(new LogFilter());
all.get(0).timestamp = 3000;
all.get(1).timestamp = 2000;
all.get(2).timestamp = 1500;
all.get(3).timestamp = 1000;
LogFilter filter = new LogFilter();
filter.startTime = 1500L;
filter.endTime = 2500L;
assert logger.read(filter).size() == 2;

Logger logger = new Logger();
logger.write("ERROR", "E1");
logger.write("ERROR", "E2");
logger.write("ERROR", "E3");
logger.write("INFO", "I1");
